class URLResolver:
    def reverse(self, lookup_view, *args, **kwargs):
        return self._reverse_with_prefix(lookup_view, "", *args, **kwargs)

# django/template/defaultfilters.py:576-585  (django.template.defaultfilters.dictsortreversed)
@register.filter(is_safe=False)
def dictsortreversed(value, arg):
    """
    Given a list of dicts, return that list sorted in reverse order by the
    property given in the argument.
    """
    try:
        return sorted(value, key=_property_resolver(arg), reverse=True)
    except (AttributeError, TypeError):
        return ""

# tests/urlpatterns_reverse/tests.py:441-444  (tests.urlpatterns_reverse.tests.URLPatternReverse.test_reverse_none)
class URLPatternReverse(SimpleTestCase):
    def test_reverse_none(self):
        # Reversing None should raise an error, not return the last un-named view.
        with self.assertRaises(NoReverseMatch):
            reverse(None)

# tests/urlpatterns_reverse/tests.py:481-487  (tests.urlpatterns_reverse.tests.URLPatternReverse.test_patterns_reported)
class URLPatternReverse(SimpleTestCase):
    def test_patterns_reported(self):
        # Regression for #17076
        with self.assertRaisesMessage(
            NoReverseMatch, r"1 pattern(s) tried: ['people/(?P<name>\\w+)/$']"
        ):
            # this url exists, but requires an argument
            reverse("people", args=[])

# tests/urlpatterns_reverse/tests.py:475-479  (tests.urlpatterns_reverse.tests.URLPatternReverse.test_non_urlsafe_prefix_with_args)
class URLPatternReverse(SimpleTestCase):
    @override_script_prefix("/%7Eme/")
    def test_non_urlsafe_prefix_with_args(self):
        # Regression for #20022, adjusted for #24013 because ~ is an unreserved
        # character. Tests whether % is escaped.
        self.assertEqual("/%257Eme/places/1/", reverse("places", args=[1]))

# tests/urlpatterns_reverse/tests.py:776-780  (tests.urlpatterns_reverse.tests.ReverseShortcutTests.test_reverse_by_path_nested)
class ReverseShortcutTests(SimpleTestCase):
    def test_reverse_by_path_nested(self):
        # Views added to urlpatterns using include() should be reversible.
        from .views import nested_view

        self.assertEqual(reverse(nested_view), "/includes/nested_path/")

# tests/urlpatterns_reverse/tests.py:546-556  (tests.urlpatterns_reverse.tests.ResolverTests.test_resolver_reverse)
class ResolverTests(SimpleTestCase):
    def test_resolver_reverse(self):
        resolver = get_resolver("urlpatterns_reverse.named_urls")
        test_urls = [
            # (name, args, kwargs, expected)
            ("named-url1", (), {}, ""),
            ("named-url2", ("arg",), {}, "extra/arg/"),
            ("named-url2", (), {"extra": "arg"}, "extra/arg/"),
        ]
        for name, args, kwargs, expected in test_urls:
            with self.subTest(name=name, args=args, kwargs=kwargs):
                self.assertEqual(resolver.reverse(name, *args, **kwargs), expected)

# tests/urlpatterns_reverse/tests.py:834-844  (tests.urlpatterns_reverse.tests.NamespaceTests.test_normal_name)
class NamespaceTests(SimpleTestCase):
    def test_normal_name(self):
        """Normal lookups work as expected."""
        test_urls = [
            ("normal-view", [], {}, "/normal/"),
            ("normal-view", [37, 42], {}, "/normal/37/42/"),
            ("normal-view", [], {"arg1": 42, "arg2": 37}, "/normal/42/37/"),
            ("special-view", [], {}, "/+%5C$*/"),
        ]
        for name, args, kwargs, expected in test_urls:
            with self.subTest(name=name, args=args, kwargs=kwargs):
                self.assertEqual(reverse(name, args=args, kwargs=kwargs), expected)

